def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    flat = [x for row in grid for x in row]
    counts = Counter(flat)
    base = counts.most_common(1)[0][0]

    # find separator color: a non-base color forming a full row or column
    sep = None
    for color in counts:
        if color == base:
            continue
        has_full_row = any(all(x == color for x in grid[r]) for r in range(H))
        has_full_col = any(all(grid[r][c] == color for r in range(H)) for c in range(W))
        if has_full_row or has_full_col:
            sep = color
            break

    hlines = []
    vlines = []
    if sep is not None:
        for r in range(H):
            if all(grid[r][c] == sep for c in range(W)):
                hlines.append(r)
        for c in range(W):
            if all(grid[r][c] == sep for r in range(H)):
                vlines.append(c)

    hsep_set = set(hlines)
    vsep_set = set(vlines)
    rstarts = [0] + [r + 1 for r in hlines]
    cstarts = [0] + [c + 1 for c in vlines]
    rstarts = [r for r in rstarts if r < H]
    cstarts = [c for c in cstarts if c < W]

    # collect rare cells (not base, not separator, not on separator lines)
    rare = []
    for r in range(H):
        if r in hsep_set:
            continue
        for c in range(W):
            if c in vsep_set:
                continue
            v = grid[r][c]
            if v != base and v != sep:
                rare.append((r, c, v))

    out = [row[:] for row in grid]
    for r, c, v in rare:
        # which block is (r, c) in?
        ri = 0
        for i, s in enumerate(rstarts):
            if s <= r:
                ri = i
        ci = 0
        for i, s in enumerate(cstarts):
            if s <= c:
                ci = i
        for i, s in enumerate(rstarts):
            for j, t in enumerate(cstarts):
                nr = s + (r - rstarts[ri])
                nc = t + (c - cstarts[ci])
                if nr < H and nc < W and grid[nr][nc] == base:
                    out[nr][nc] = v
    return out
